E, n = maker()

n("פרומט", "פרומט הוא שם ביידיש, וכנראה הוא בא מהמילה היידית פרום, אדוק וירא שמיים. ביידיש נבנו שמות רבים ממילים של תכונות טובות, כמו פרומט, שיינא וגוטה. השם היה נפוץ בקהילות של מזרח אירופה, ונשמר בקהילות חסידיות.", [])
n("רחמים", "רחמים היא מילה עברית לחמלה ולחסד, והיא באה מהשורש ר־ח־ם, שממנו גם המילה רחם. כשם, רחמים היה נפוץ מאוד בקהילות של יהודי צפון אפריקה, עיראק ותימן, לפעמים כשם שניתן בתקווה לחסד מן השמיים. השם ניתן לבנים.", [])
n("שלומית", "שלומית הוא שם עברי מהמילה שלום, והוא מופיע כבר בתורה ובספרים נוספים של התנ״ך, כשמן של כמה נשים ושל כמה גברים. מאותו שורש באים גם השמות שלמה, שולמית ושלום. השם היה נפוץ בארץ מאז ימי היישוב.", ["שולמית"])
n("שריי", "שריי הוא כתיב של שרי, שמה הראשון של שרה אמנו, לפני שאלוהים שינה את שמה. שני השמות באים כנראה מהמילה שרה, נסיכה. הכתיב עם שתי אותיות י מסמן את ההגייה של הסוף, ונשמע כמו שָׂרַי.", ["שרה", "שרי"])
n("עינת", "עינת הוא שם עברי חדש, שקשור למילים עין ומעיין. המעיין הוא מקור של מים זורמים, והוא נזכר בשמות של מקומות רבים בארץ, כמו עין גדי ועין הוד. השם היה נפוץ בארץ בשנות השבעים, ויש גם יישוב בשם עינת ליד ראש העין.", ["עיינה"])
n("אבירם", "אבירם הוא שם מקראי שבנוי מהמילים אבי ורם, ופירושו אבי נעלה. בספר במדבר אבירם הוא אחד המורדים במשה, יחד עם קורח ודתן. בעברית החדשה השם היה נפוץ בשנות החמישים והשישים.", [])
n("בת חן", "בת חן הוא שם עברי חדש שבנוי משתי מילים, בת וחן, ופירושו מלאת חן. בעברית הצירוף בת עם מילה של תכונה מתאר מי שהתכונה הזאת היא חלק ממנה. השם נכתב לפעמים כמילה אחת, בתחן, ולפעמים עם מקף.", [])
n("לידר", "לידר היא המילה ביידיש ובגרמנית לשירים, ריבוי של ליד, שיר. בגרמנית לידר הוא גם שם של סוגה של שירים לקול ולפסנתר. בעברית השם נשמע קרוב ללידור, שבנוי מהמילים לי ודור.", ["לידור"])
n("יוליה", "יוליה היא צורת הנקבה של יוליוס, שמה של משפחה ידועה ברומא העתיקה, שממנה בא יוליוס קיסר. השם נפוץ מאוד ברוסית ובשפות של מזרח אירופה, ובאנגלית מוכרת הצורה ג׳וליה. החודש יולי נקרא על שם יוליוס קיסר.", ["יולי"])
n("תאי", "תאי הוא שם קצר וחדש, וכנראה הוא צורה קצרה של תאיר, שבא מהשורש א־ו־ר, אור. יש גם הסבר שלפיו השם בא מהמילה תא, חדר קטן. השם ניתן גם לבנים וגם לבנות.", ["תאיה", "תאה"])
n("רומן", "רומן הוא שם סלאבי שבא מהשם הלטיני רומנוס, רומאי, איש מהעיר רומא. ברוסית, באוקראינית ובפולנית השם נפוץ מאוד. בעברית המילה רומן מתארת גם סיפור ארוך, וגם קשר של אהבה.", [])
n("ליזה", "ליזה היא צורת חיבה של אליזבת, שהיא הצורה האירופית של השם העברי אלישבע. במסורת אלישבע היא אשתו של אהרן הכהן. ליזה נפוץ ברוסית, באיטלקית ובשפות נוספות.", ["ליז", "ליזי"])
n("עלקא", "עלקא הוא שם ביידיש, צורה של אלקה, שם שהיה נפוץ בגרמנית וביידיש כצורת חיבה של אדלהייד. ביידיש נכתבת התנועה באות ע, ולכן השם נכתב כך. השם נשמר בקהילות חסידיות.", ["אלקה"])
n("לורי", "לורי הוא שם קצר, צורת חיבה של לורה ושל לורן, שמות שבאים מהמילה הלטינית לאורוס, עץ הדפנה. באנגלית לורי הוא שם בפני עצמו. בעברית השם נשמע קרוב גם ללירי וללורין.", ["לורין"])
n("אריאן", "אריאן הוא שם בינלאומי, וכנראה הוא צורה של אריאנה, שם שבא מהשם היווני אריאדנה. בצרפתית השם נכתב אריאן. בעברית הוא נשמע קרוב לשמות אריאל ואוריאן.", ["אריאנה"])
n("דמיטרי", "דמיטרי הוא שם רוסי שבא מהשם היווני דמטריוס, שקשור לדמטר, אלת האדמה והיבול ביוון העתיקה. ברוסית ובאוקראינית השם נפוץ מאוד, ומוכרת גם צורת החיבה דימה. השם הגיע לארץ עם העלייה מברית המועצות.", [])
n("מייק", "מייק הוא קיצור אנגלי של מייקל, הצורה האנגלית של מיכאל. השם מיכאל בנוי מהמילים מי, כ ואל, ופירושו מי כמו האל. באנגלית מייק נעשה שם בפני עצמו, ומוכר בכל העולם.", ["מיכאל"])
n("ג'סיקה", "ג׳סיקה הוא שם אנגלי, וכנראה הוא בא מהשם העברי יסכה. השם נעשה מוכר באנגלית בזכות מחזה של שייקספיר. בשנות השמונים והתשעים הוא היה אחד הנפוצים בעולם דובר האנגלית.", [])
n("אושרית", "אושרית הוא שם עברי מהמילה אושר, שמחה ושלווה. מאותו שורש, א־ש־ר, באים גם השמות אושרת, אושרה ואושרי. השם היה נפוץ בארץ בשנות השבעים והשמונים, וניתן לבנות.", ["אושרת", "אושרה"])
n("איילין", "איילין הוא שם אירי ואנגלי, וכנראה הוא צורה של הלן, שם יווני שקשור למילה לאור. באירלנד ובסקוטלנד השם נפוץ מאוד. בעברית הוא נשמע גם קרוב לאיילה ולאיילת.", [])
n("שאנל", "שאנל הוא שם צרפתי, שהיה במקור שם משפחה, ופירושו לפי אחד ההסברים תעלה או ערוץ. השם מוכר בעולם בזכות בית האופנה הצרפתי. בעברית מוכר גם הכתיב שנאל.", ["שנאל"])
n("עטיל", "עטיל הוא שם עברי חדש, וכנראה הוא קשור למילה עטרה, כתר וקישוט לראש. השם נשמע קרוב לעטל ולעטרה. כמו שמות עבריים חדשים רבים, הוא קצר ובעל צליל רך.", ["עטל"])
n("קרינה", "קרינה הוא שם בינלאומי, וכנראה הוא בא מהמילה הלטינית קרה, יקרה ואהובה. השם נפוץ ברוסית, באיטלקית ובשפות נוספות. בעברית המילה קרינה מתארת גם את האור והחום שיוצאים מגוף מאיר.", ["קרין"])
n("גלית", "גלית הוא שם עברי חדש מהמילה גל, גל של מים בים. מאותה מילה באים גם השמות המוכרים גל, גלי וגליה. השם היה נפוץ בארץ בשנות השישים והשבעים, וניתן לבנות, והוא מביא תמונה של ים.", ["גלי", "גל"])
n("סטיבן", "סטיבן הוא הצורה האנגלית של השם היווני סטפנוס, שפירושו כתר או זר. השם נפוץ מאוד באנגלית, ובשפות אחרות מוכרות הצורות סטפן ואסטבן. בעברית השם נשמע ומוכר בעיקר במשפחות דוברות אנגלית.", ["סטפן"])
n("איטא", "איטא הוא שם ביידיש, וכנראה הוא צורה של יהודית. ביידיש נבנו מיהודית הרבה צורות, למשל איטה, יוטא ויוטה. השם היה נפוץ בקהילות של מזרח אירופה, ונשמר בקהילות חסידיות.", ["איטה"])
n("סיגל", "סיגל הוא שם עברי חדש, שנשמע כמו שם הפרח סיגלית, פרח סגול וריחני. יש שקושרים אותו גם למילה סגולה, אוצר יקר, מילה עתיקה לדבר יקר שאדם שומר לעצמו. השם היה נפוץ בארץ בשנות השישים והשבעים.", ["סיגלית"])
n("עמיר", "עמיר היא מילה עברית לאלומה של שיבולים קצורות, שקושרים יחד בשדה בזמן הקציר. השם מביא תמונה של שדה ושל יבול. בעברית החדשה השם היה נפוץ בשנות החמישים והשישים, ויש גם קיבוץ בשם עמיר בעמק החולה.", ["עמירה"])
n("יפעת", "יפעת היא מילה עברית לזוהר ולהופעה מרשימה, והיא קשורה לשורש י־פ־ע, שממנו באה גם המילה הופיע. זו מילה עתיקה, שנשמעת חגיגית גם היום. השם היה נפוץ בארץ בשנות השישים והשבעים, ויש גם קיבוץ בשם יפעת בעמק יזרעאל.", [])
n("הני", "הני הוא שם קצר, צורת חיבה של חנה, שהייתה נפוצה בשפות של אירופה. באנגלית המילה הוני פירושה דבש, ולכן לשם יש צליל מתוק גם באנגלית. השם ניתן בעיקר לבנות.", ["הניה"])
n("בריינדל", "בריינדל הוא שם יידי, וכנראה הוא צורת חיבה שנבנתה מהמילה היידית ברוין, חום, כמו צבע של שיער. ביידיש צורות חיבה רבות נבנו עם הסיומת דל. השם היה נפוץ בקהילות של מזרח אירופה.", [])
n("ליבר", "ליבר הוא שם ביידיש, וכנראה הוא בא מהמילה היידית ליב, אהוב ויקר. ביידיש נבנו מאותה מילה גם השמות ליבא וליבע. השם ניתן גם לבנים וגם לבנות, והוא נשמר בעיקר בקהילות חסידיות.", [])
n("לירם", "לירם הוא שם עברי חדש שבנוי משתי מילים, לי ורם, ופירושו שלי, הנעלה. המילה רם פירושה גבוה ונעלה. השם נשמע קרוב ללירון וללירום, וניתן בעיקר לבנים.", ["לירום"])
n("אלארי", "אלארי הוא שם חדש, וכנראה הוא בנוי מהמילים אל וארי, אריה, ופירושו אלוהים אריה. השם נשמע קרוב לאלאור ולאריאל. בפינית יש שם בצליל דומה, אלארי, שמקורו אחר.", [])
n("אריקה", "אריקה היא צורת הנקבה של אריק, שם שבא מנורדית עתיקה ופירושו שליט לנצח. אריקה הוא גם שמו של שיח קטן עם פרחים ורודים, שמכסה גבעות באירופה. השם נפוץ באנגלית ובגרמנית.", ["אריק"])
n("טאי", "טאי הוא שם קצר שמופיע בכמה שפות עם מקורות שונים. באנגלית הוא צורה קצרה של שמות כמו טיילר, ובשפות של מזרח אסיה יש לו משמעויות אחרות. בעברית השם נשמע קצר וקליל.", ["טאיה"])
n("רונית", "רונית הוא שם עברי מהמילה רון, שירה ושמחה, מהשורש ר־נ־ן. מאותו שורש באים גם השמות המוכרים רוני, רינה ורנן. השם היה נפוץ מאוד בארץ בשנות החמישים והשישים.", ["רוני"])
n("לבנה", "לבנה היא מילה עתיקה לירח, והיא קשורה לצבע הלבן של אורו. בשיר השירים היא מופיעה בתיאור של יופי, יפה כלבנה. בעברית של היום המילה לבנה מתארת גם גבינה רכה, וגם אבן בנייה, לבֵנה.", ["ליבנה"])
n("חסיה", "חסיה הוא שם עברי, וכנראה הוא בנוי מהמילים חוסה ויה, ופירושו מחסה באלוהים. השם היה נפוץ בקהילות של מזרח אירופה. מאותו שורש באות המילים מחסה וחסות.", [])
n("מרטין", "מרטין הוא שם שבא מהשם הלטיני מרטינוס, שקשור למרס, אל המלחמה ברומא העתיקה. השם נפוץ בשפות רבות של אירופה, והוא שמו של קדוש ידוע מימי הביניים. בעברית השם ניתן בעיקר לבנים.", ["מרטינה"])
n("נורית", "נורית היא פרח בר אדום שפורח בחורף ובאביב בשדות של הארץ. היא נראית דומה לכלנית, ושתיהן צובעות את הגבעות באדום. השם נבנה גם מהמילה נור, אור, והיה נפוץ בארץ בשנות החמישים.", [])
n("עטי", "עטי הוא שם קצר, צורת חיבה של עטרה, כתר וקישוט לראש. השם היה נפוץ בעיקר בדורות הקודמים. הוא נשמע קרוב גם לעטיא, צורה נוספת של אותו שם, ולעטרה עצמה.", ["עטיא"])
n("ויקטור", "ויקטור היא המילה הלטינית למנצח, ומאותה מילה באה גם המילה ויקטוריה, ניצחון. השם נפוץ בשפות רבות של אירופה, וגם בקהילות יהודיות של צפון אפריקה. בעברית השם ניתן לבנים.", ["ויקטוריה"])
n("ליז", "ליז הוא קיצור של אליזבת, הצורה האירופית של השם העברי אלישבע. באנגלית ובצרפתית ליז הוא שם בפני עצמו. השם קצר מאוד, ונוח במשפחות שחיות בין שתי שפות.", ["ליזה", "ליזי"])
n("גדליהו", "גדליהו הוא שם מקראי שבנוי מהמילה גדל ומהסיומת יהו, ופירושו ה׳ גדול. גדליהו בן אחיקם מונה לנציב יהודה אחרי חורבן הבית הראשון, ונרצח, ועל שמו נקבע צום גדליה. השם מוכר גם בצורה גדליה.", ["גדליה"])
n("שינא", "שינא הוא שם ביידיש, שבא מהמילה היידית שיין, יפה. ביידיש מוכרות גם הצורות שיינא ושיינדל. השם היה נפוץ בקהילות של מזרח אירופה, ונשמר בקהילות חסידיות.", ["שיינא", "שיין"])
n("שיילי", "שיילי הוא שם חדש, וכנראה הוא צורה של שילי, שבנוי מהמילים שי ולי, מתנה בשבילי. הכתיב עם שתי אותיות י מסמן הגייה שמזכירה את האנגלית. השם ניתן בעיקר לבנות.", ["שילי"])
n("יונית", "יונית הוא שם עברי חדש, צורה של יונה, הציפור שמסמלת שלום. מאותה מילה באים גם השמות יונה ויוני. השם היה נפוץ בארץ בשנות השישים, והוא נשמע רך וקליל, כמו מעוף של ציפור.", ["יונה"])
n("ליעוז", "ליעוז הוא שם עברי חדש שבנוי משתי מילים, לי ועוז, ופירושו יש לי כוח. המילה עוז היא מילה עתיקה לכוח ולאומץ. מוכרת גם הצורה לי־עוז, עם מקף בין שתי המילים.", ["לי-עוז"])
n("דון", "דון הוא שם אנגלי, וכנראה הוא צורה קצרה של דונלד. בשפה הספרדית ובאיטלקית דון הוא גם תואר של כבוד לאדם מכובד. ברוסיה דון הוא שמו של נהר גדול, שזורם אל ים אזוב.", [])
n("היאלי", "היאלי הוא שם עברי חדש, וכנראה הוא בנוי מהמילים היא ולי, ופירושו היא שלי. כמו שמות עבריים חדשים רבים, הוא מצרף מילים קצרות לשם אחד. השם ניתן בעיקר לבנות.", [])
n("מירה", "מירה הוא שם שנפוץ בשפות רבות, עם מקורות שונים. בעברית הוא נחשב לקיצור של מרים, בסלאבית הוא קשור למילה מיר, שלום, ובלטינית למילה מירה, נפלאה. השם היה נפוץ בארץ בשנות החמישים.", ["מירי", "מירית"])
n("איזבל", "איזבל היא צורה אירופית של השם העברי אלישבע, שהתפתחה בשפה הספרדית ובצרפתית. השם נפוץ מאוד בשפות רבות, ומוכרת גם הצורה איזבלה. בעברית השם נשמע גם כמו איזבל המקראית, אבל אלה שני שמות שונים.", ["איזבלה"])
n("סשה", "סשה הוא צורת חיבה רוסית של אלכסנדר ושל אלכסנדרה, שם יווני שפירושו מגן על האנשים. ברוסית הוא ניתן גם לבנים וגם לבנות. השם הגיע לארץ עם העלייה מברית המועצות.", [])
n("סטפני", "סטפני היא צורת הנקבה הצרפתית של סטפן, שם שבא מהמילה היוונית סטפנוס, כתר. השם נפוץ בצרפתית ובאנגלית. בעברית מוכר גם הכתיב סטפאני, והשם נשמע כמעט אותו דבר בכל השפות.", ["סטפן"])
n("אנדריי", "אנדריי הוא צורה סלאבית של השם היווני אנדראס, שבא מהמילה אנר, גבר, ופירושו אמיץ. ברוסית ובאוקראינית השם נפוץ מאוד. בשפות אחרות מוכרות הצורות אנדרו ואנדרה.", [])
n("סיאל", "סיאל הוא שם חדש, וכנראה הוא כתיב אחר של שיאל, שבנוי מהמילים שי ואל, מתנה מאלוהים. בכתיב עם האות ס השם נשמע מעט אחרת. השם ניתן בעיקר לבנות, והוא קצר ורך.", ["שיאל"])
n("בני", "בני הוא שם קצר, צורת חיבה של בנימין, במסורת בנו הצעיר של יעקב. בעברית השם נשמע גם כמו המילה בני, הבן שלי. השם היה נפוץ בארץ בשנות החמישים והשישים.", ["בנימין"])
n("הינדל", "הינדל הוא צורת חיבה יידית של הינדה, שם שבא מהמילה היידית הינד, איילה. ביידיש צורות חיבה רבות נבנו עם הסיומת ל. השם קשור בעקיפין לשם העברי איילה.", [])
n("ארתור", "ארתור הוא שם בינלאומי שמקורו כנראה בשפות הקלטיות, ויש שקושרים אותו למילה דוב. השם מוכר מאוד בזכות האגדות על המלך ארתור. ברוסית ובשפות של מזרח אירופה השם נפוץ, ומשם הגיע לארץ.", [])
